from inventory import Inventory, InventoryError


def test_simple_batch():
    inv = Inventory({"apple": 5, "pear": 2})
    inv.apply_orders([("apple", 2), ("pear", 1)])
    assert inv.stock == {"apple": 3, "pear": 1}


def test_cannot_go_negative():
    inv = Inventory({"apple": 1})
    with pytest.raises(InventoryError):
        inv.apply_orders([("apple", 2)])


def test_apply_orders_atomicity():
    inv = Inventory({"apple": 5, "pear": 2})
    # The second order for pear will fail because it's unknown or insufficient? 
    # Let's use an unknown SKU for the second order.
    with pytest.raises(InventoryError):
        inv.apply_orders([("apple", 2), ("banana", 1)])
    # Apple should NOT have been reduced
    assert inv.stock == {"apple": 5, "pear": 2}


def test_apply_orders_unknown_sku():
    inv = Inventory({"apple": 5})
    with pytest.raises(InventoryError):
        inv.apply_orders([("banana", 1)])


def test_apply_orders_insufficient_stock_total():
    inv = Inventory({"apple": 5})
    # Two orders for apple, total 6 > 5
    with pytest.raises(InventoryError):
        inv.apply_orders([("apple", 3), ("apple", 3)])
    assert inv.stock == {"apple": 5}


def test_apply_orders_invalid_qty_type():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.apply_orders([("apple", "1")])
    assert inv.stock == {"apple": 5}


def test_apply_orders_invalid_qty_value():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.apply_orders([("apple", 0)])
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.apply_orders([("apple", -1)])
    assert inv.stock == {"apple": 5}


def test_apply_orders_multiple_orders_same_sku_success():
    inv = Inventory({"apple": 5})
    inv.apply_orders([("apple", 2), ("apple", 2)])
    assert inv.stock == {"apple": 1}


def test_restock_invalid_qty_type():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.restock("apple", "1")
    assert inv.stock == {"apple": 5}


def test_restock_invalid_qty_value():
    inv = Inventory({"apple": 5})
    with pytest.raises(ValueError):
        inv.restock("apple", 0)
    assert inv.stock == {"apple": 5}

    with pytest.raises(ValueError):
        inv.restock("apple", -1)
    assert inv.stock == {"apple": 5}

def test_restock_valid():
    inv = Inventory({"apple": 5})
    inv.restock("apple", 3)
    assert inv.stock == {"apple": 8}
    inv.restock("banana", 2)
    assert inv.stock == {"apple": 8, "banana": 2}
